S['NONG1911A'] = [{'k': 'noti', 'ch': 'Mở đầu', 'cap': ('XĂNG E5 TỪ 30.114 ĐỒNG', 'CÒN 19.399 ĐỒNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'noti': {'gio': '07:30', 'ngay': 'Thứ Năm', 'items': [('Tin tức', 'Giá xăng', 'Chiều nay giá xăng điều chỉnh kỳ mới', (255, 196, 0)), ('Vợ', 'Tin nhắn', 'Xăng rẻ vậy sao đi chợ vẫn đắt anh?', (56, 189, 248))]}, 'say': 'Bảy giờ rưỡi sáng nay, anh Thắng, người chạy giao hàng ở Thành phố Hồ Chí Minh, đổ đầy bình xăng. Một lít xăng Enăm giờ chỉ còn hơn mười chín nghìn ba trăm đồng. Tháng ba năm nay, cùng lít xăng đó có lúc lên tới hơn ba mươi nghìn. Chiều nay giá xăng lại điều chỉnh kỳ mới. Nhưng tin nhắn của vợ anh mới là câu hỏi đáng nghĩ: xăng rẻ vậy, sao đi chợ vẫn đắt hả anh?'}, {'k': 'bignum', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('XĂNG E5 RẺ ĐI', 'GẦN 36% TỪ ĐỈNH'), 'cols': ((255, 255, 255), (255, 196, 0)), 'value': 10715, 'fmt': '{:,.0f}', 'unit': ' đồng', 'top': 'XĂNG E5 RẺ HƠN MỖI LÍT, SO VỚI ĐỈNH THÁNG 3', 'sub': 'Từ 30.114 còn 19.399 đồng (kỳ 12/11/2026)', 'col': (255, 196, 0), 'say': 'Theo báo Ngôi Sao, từ đỉnh tháng ba đến kỳ điều hành tuần trước, mỗi lít xăng Enăm đã rẻ đi mười nghìn bảy trăm mười lăm đồng, tức gần ba mươi sáu phần trăm. Vậy mà theo Cục Thống kê, giá cả nói chung tháng mười vẫn cao hơn năm ngoái năm phần trăm. Tiền xăng rẻ đi đâu? Ai thật sự được lợi? Và lúc nào xăng có thể đắt lại?'}, {'k': 'giay', 'ch': 'Chương 1 – Giá xăng năm 2026', 'cap': ('GIÁ XĂNG E5 NĂM 2026', 'TỪ ĐỈNH VỀ ĐẾN HÔM NAY'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'giay': {'tieu_de': 'GIÁ XĂNG E5 MỖI LÍT', 'so': 'Theo VietnamPlus 31/10, Ngôi Sao 18/11/2026', 'dau': 'ĐÃ ĐỌC', 'dieu': [('Tháng 3/2026, lúc cao nhất: 30.114 đồng.', 'ĐỈNH'), ('Trước ngày 1/11: khoảng 26.000 đồng.', 'VẪN CAO'), ('Ngày 1/11, thuế về 0%: 24.223 đồng.', 'GIẢM 1.804'), ('Kỳ 12/11: 19.399 đồng.', 'GIẢM 6.628')]}, 'say': 'Anh Thắng ghi lại đường đi của lít xăng. Tháng ba, khi xung đột quanh Iran làm eo biển Hormuz bị phong toả, xăng Enăm lên hơn ba mươi nghìn đồng. Cuối tháng mười vẫn còn khoảng hai mươi sáu nghìn. Ngày một tháng mười một, thuế tiêu thụ đặc biệt với xăng về không phần trăm, giá giảm một nghìn tám trăm linh bốn đồng. Rồi đến kỳ điều hành tuần trước, chỉ còn mười chín nghìn ba trăm chín mươi chín đồng. Chỉ trong nửa tháng, mỗi lít rẻ đi hơn sáu nghìn sáu trăm đồng.'}, {'k': 'chat', 'cap': ('"XĂNG GIẢM RỒI', 'SAO RAU THỊT CHƯA GIẢM?"'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'chat': {'ten': 'Vợ', 'tv': 'Đang hoạt động', 'gio': '08:05', 'mau': (56, 189, 248), 'msgs': [('Vợ', 'Xăng giảm cả tháng nay rồi'), ('Vợ', 'Mà rau, thịt, tiền gửi xe vẫn y nguyên'), ('me', 'Để anh tìm hiểu xem sao')]}, 'say': 'Chị Mai, vợ anh, bán cơm văn phòng. Chị nhắn tiếp: xăng giảm cả tháng nay rồi, mà rau, thịt, tiền gửi xe vẫn y nguyên. Anh Thắng trả lời: để anh tìm hiểu xem sao. Và con số đầu tiên anh tìm được làm anh bất ngờ.'}, {'k': 'bignum', 'anh': 'ov:Ben Thanh Market||Ben Thanh Market', 'cap': ('GIÁ CẢ THÁNG 10', 'VẪN CAO HƠN NĂM NGOÁI 5,09%'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'value': 5.09, 'fmt': '{:,.2f}', 'unit': '%', 'top': 'CPI THÁNG 10/2026 SO VỚI CÙNG KỲ', 'sub': 'Theo Cục Thống kê, công bố 3/11/2026', 'col': (239, 68, 68), 'say': 'Theo Cục Thống kê, chỉ số giá tiêu dùng tháng mười cao hơn cùng kỳ năm ngoái khoảng năm phẩy một phần trăm. Tính bình quân mười tháng, giá cả tăng gần bốn phẩy sáu phần trăm, đã vượt mức mục tiêu khoảng bốn phẩy năm phần trăm cho cả năm. Xăng rẻ đi, nhưng mặt bằng giá chưa hề lùi.'}, {'k': 'cards', 'ch': 'Chương 2 – Vì sao xăng rẻ mà chợ không rẻ?', 'anh': 'ov:Ben Thanh Market||Ben Thanh Market', 'cap': ('BỎ XĂNG RA', 'GIÁ CẢ VẪN TĂNG HƠN 4%'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('4,24%', 'Lạm phát cơ bản 10 tháng', 'BỎ XĂNG, RAU THỊT TƯƠI'), ('4,57%', 'CPI bình quân 10 tháng', 'VƯỢT MỤC TIÊU 4,5%'), ('0,34%', 'Ngân hàng dự báo CPI tháng 11', 'VẪN TĂNG')], 'say': 'Có một con số giúp anh Thắng hiểu ra. Đó là lạm phát cơ bản, tức là giá cả sau khi đã bỏ xăng dầu, lương thực và thực phẩm tươi sống ra. Bình quân mười tháng, con số này vẫn tăng hơn bốn phẩy hai phần trăm. Nghĩa là những thứ không dính tới xăng vẫn đang lên giá đều đặn. Ngân hàng Nhà nước vừa công bố khảo sát hôm qua.'}, {'k': 'cards', 'anh': 'ov:Ben Thanh Market||Ben Thanh Market', 'cap': ('BỎ XĂNG RA', 'GIÁ CẢ VẪN TĂNG HƠN 4%'), 'cols': ((255, 255, 255), (255, 196, 0)), 'cards': [('4,24%', 'Lạm phát cơ bản 10 tháng', 'BỎ XĂNG, RAU THỊT TƯƠI'), ('4,57%', 'CPI bình quân 10 tháng', 'VƯỢT MỤC TIÊU 4,5%'), ('0,34%', 'Ngân hàng dự báo CPI tháng 11', 'VẪN TĂNG')], 'say': 'Các ngân hàng vẫn dự báo giá cả tháng mười một tăng thêm khoảng không phẩy ba phần trăm so với tháng mười, dù xăng và điện đều giảm.'}, {'k': 'noti', 'cap': ('THUẾ XĂNG VỀ 0%', 'CHỈ ĐẾN HẾT 31/3/2027'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'noti': {'gio': '09:20', 'ngay': 'Thứ Năm', 'items': [('Tin tức', 'Chính sách', 'Thuế tiêu thụ đặc biệt với xăng 0% đến hết 31/3/2027', (255, 196, 0)), ('Tin tức', 'Chính sách', 'Giá điện bình quân giảm 2% từ ngày 1/11', (34, 197, 94))]}, 'say': 'Anh Thắng đọc tiếp tin chính sách. Theo Nghị quyết bốn mươi lăm của Chính phủ, thuế tiêu thụ đặc biệt với xăng về không phần trăm từ ngày một tháng mười một. Nhưng mức thuế này chỉ áp dụng đến hết ngày ba mươi mốt tháng ba năm hai nghìn không trăm hai mươi bảy. Ngân sách giảm thu gần bảy nghìn tỷ đồng. Cùng ngày, giá điện bình quân cũng giảm hai phần trăm.'}, {'k': 'bignum', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('2 BIỆN PHÁP', 'KÉO CPI CẢ NĂM XUỐNG 0,08 ĐIỂM'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'value': 0.08, 'fmt': '{:,.2f}', 'unit': ' điểm %', 'top': 'TÁC ĐỘNG LÊN CPI BÌNH QUÂN NĂM 2026', 'sub': 'Ước tính của Bộ Tài chính (Báo Đầu tư 4/11/2026)', 'col': (255, 196, 0), 'say': 'Và đây là cú lật. Theo ước tính của Bộ Tài chính, cả hai biện pháp, xăng và điện, chỉ kéo chỉ số giá bình quân năm nay xuống chưa đến không phẩy một điểm phần trăm. Vì sao ít vậy? Vì trong rổ hàng tính giá, điện và xăng dầu cộng lại chỉ chiếm hơn chín phần trăm. Hơn chín mươi phần trăm còn lại là ăn uống, nhà ở, học hành, thuốc men, và những thứ đó không giảm theo xăng.'}, {'k': 'chat', 'cap': ('"GIÁ LÊN THÌ NHANH', 'GIÁ XUỐNG THÌ CHẬM"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Chị Mai', 'tv': 'Đang hoạt động', 'gio': '11:15', 'mau': (56, 189, 248), 'msgs': [('Chị Mai', 'Tháng ba xăng lên, rau thịt lên theo liền'), ('Chị Mai', 'Giờ xăng xuống, chưa mối nào hạ giá cho em'), ('me', 'Vậy suất cơm em có hạ không?')]}, 'say': 'Chị Mai kể thêm từ phía người bán. Tháng ba, xăng vừa lên là mối rau, mối thịt báo tăng giá ngay. Giờ xăng xuống cả tháng, chưa mối nào hạ giá cho chị. Anh Thắng hỏi lại: vậy suất cơm của em có hạ không? Chị trả lời rằng chị cũng chưa hạ, vì tiền chợ chưa giảm đồng nào.'}, {'k': 'call', 'ch': 'Chương 3 – Lần trước là năm 2022', 'cap': ('"NĂM 2022 XĂNG CŨNG', 'GIẢM MỘT MẠCH"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'call': {'ten': 'Bố', 'phu': 'Chạy xe ôm 20 năm', 'mau': (255, 196, 0), 'loi': ['Năm 2022 xăng gần 33 nghìn', 'Cuối năm còn hơn 21 nghìn']}, 'say': 'Trưa đó anh Thắng gọi cho bố, người chạy xe ôm hơn hai mươi năm. Bố kể: năm hai nghìn không trăm hai mươi hai cũng y như vậy. Giữa năm xăng gần ba mươi ba nghìn một lít, ai cũng than. Cuối năm giảm một mạch xuống hơn hai mươi mốt nghìn. Nhưng bát phở đầu ngõ thì không quay về giá cũ.'}, {'k': 'giay', 'cap': ('NĂM 2022', 'NHỮNG CON SỐ CỦA LẦN TRƯỚC'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'giay': {'tieu_de': 'NHỮNG CON SỐ CỦA LẦN TRƯỚC', 'so': 'Theo VnExpress 12/12/2022, Tuổi Trẻ 29/12/2022', 'dau': 'SO SÁNH', 'dieu': [('Xăng RON95 tháng 6/2022: 32.870 đồng.', 'ĐỈNH'), ('Ngày 12/12/2022: 21.200 đồng.', 'RẺ GẦN 36%'), ('CPI tháng 12/2022 so cùng kỳ: 4,55%.', 'VẪN TĂNG'), ('CPI bình quân năm 2022: 3,15%.', 'THẤP HƠN')]}, 'say': 'Những con số của lần trước. Tháng sáu năm hai nghìn không trăm hai mươi hai, theo VnExpress, xăng RONchín mươi lăm lên đỉnh ba mươi hai nghìn tám trăm bảy mươi đồng. Đến giữa tháng mười hai, chỉ còn hai mươi mốt nghìn hai trăm, rẻ đi gần ba mươi sáu phần trăm. Thế nhưng theo Tổng cục Thống kê, giá cả tháng mười hai năm hai nghìn không trăm hai mươi hai vẫn cao hơn cùng kỳ khoảng bốn phẩy sáu phần trăm. Cao hơn hẳn mức bình quân chỉ hơn ba phần trăm của cả năm. Xăng xuống nửa năm trời, giá cả chung vẫn đi lên.'}, {'k': 'bars', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('XĂNG RON95 RẺ ĐI TỪ ĐỈNH', 'LẦN TRƯỚC VÀ LẦN NÀY'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'bars': [('Năm 2022', 35.5, (255, 196, 0), '35,5%'), ('Năm 2026', 36.8, (34, 197, 94), '36,8%')], 'say': 'Đặt hai lần cạnh nhau, giống đến bất ngờ. Năm hai nghìn không trăm hai mươi hai, xăng RONchín mươi lăm rẻ đi khoảng ba mươi lăm phẩy năm phần trăm từ đỉnh. Năm nay, xăng RONchín mươi lăm loại Emười lên đỉnh ba mươi mốt nghìn bốn trăm hai mươi đồng ngày hai mươi tư tháng ba. Kỳ tuần trước còn mười chín nghìn tám trăm bốn mươi lăm đồng, rẻ đi khoảng ba mươi sáu phẩy tám phần trăm.'}, {'k': 'checklist', 'anh': 'ov:Hanoi skyline night||Hanoi skyline night', 'cap': ('GIỐNG 2, KHÁC 2', 'SO VỚI NĂM 2022'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Giống: xăng rẻ đi hơn 35%', (255, 196, 0)), ('Giống: giá cả chung vẫn tăng', (239, 68, 68)), ('Khác: nhờ thuế 0% có hạn', (239, 68, 68)), ('Khác: đô la cao nhất 19 tháng', (239, 68, 68))], 'say': 'So với năm hai nghìn không trăm hai mươi hai, có hai điểm giống và hai điểm khác. Giống ở chỗ xăng rẻ đi hơn ba mươi lăm phần trăm từ đỉnh, và giá cả chung vẫn tăng. Khác ở chỗ lần này giá xăng còn được đỡ bởi thuế tiêu thụ đặc biệt về không, mà mức thuế đó có ngày hết hạn. Và theo Báo Quốc tế, đồng đô la vừa lên cao nhất mười chín tháng, trong khi dầu mua bằng đô la. Giá dầu Brent hôm mười bảy tháng mười một vẫn quanh chín mươi ba đô la một thùng.'}, {'k': 'checklist', 'anh': 'ov:Hanoi skyline night||Hanoi skyline night', 'cap': ('GIỐNG 2, KHÁC 2', 'SO VỚI NĂM 2022'), 'cols': ((255, 255, 255), (255, 196, 0)), 'items': [('Giống: xăng rẻ đi hơn 35%', (255, 196, 0)), ('Giống: giá cả chung vẫn tăng', (239, 68, 68)), ('Khác: nhờ thuế 0% có hạn', (239, 68, 68)), ('Khác: đô la cao nhất 19 tháng', (239, 68, 68))], 'say': 'Xăng rẻ hôm nay không có nghĩa là sẽ rẻ mãi.'}, {'k': 'giay', 'ch': 'Chương 4 – Sổ chi tiêu nhà anh Thắng', 'cap': ('TIỀN XĂNG RẺ ĐI GẦN 700 NGHÌN', 'TIỀN CHỢ ĐẮT THÊM HƠN 300 NGHÌN'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'giay': {'tieu_de': 'SỔ CHI TIÊU MỖI THÁNG', 'so': 'Số giả định để minh hoạ', 'dau': 'GIẢ ĐỊNH', 'dieu': [('Đổ 65 lít xăng E5 mỗi tháng.', '65 LÍT'), ('Tháng 3: gần 2 triệu tiền xăng.', 'GẦN 2 TRIỆU'), ('Bây giờ: khoảng 1,26 triệu.', 'BỚT GẦN 700 NGHÌN'), ('Tiền chợ 6 triệu, tăng 5,09%.', 'THÊM HƠN 300 NGHÌN')]}, 'say': 'Tối đó anh Thắng mở sổ chi tiêu. Em giả định để minh hoạ: anh chạy giao hàng, mỗi tháng đổ khoảng sáu mươi lăm lít xăng Enăm. Tháng ba, tiền xăng gần hai triệu đồng. Bây giờ còn khoảng một triệu hai trăm sáu mươi nghìn, bớt gần bảy trăm nghìn đồng mỗi tháng. Nhưng tiền chợ của nhà anh khoảng sáu triệu mỗi tháng, nếu đắt hơn năm ngoái năm phần trăm, là thêm hơn ba trăm nghìn. Phần lợi từ xăng đã bị chợ lấy lại gần một nửa.'}, {'k': 'chat', 'cap': ('"THÁNG NÀY DƯ TIỀN', 'SAO KHÔNG THẤY ĐÂU?"'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'chat': {'ten': 'Chị Mai', 'tv': 'Đang hoạt động', 'gio': '21:00', 'mau': (56, 189, 248), 'msgs': [('Chị Mai', 'Tháng này đáng lẽ dư tiền xăng'), ('Chị Mai', 'Mà cuối tháng em không thấy đồng nào'), ('me', 'Tại nó tan vào chi tiêu hết rồi')]}, 'say': 'Chị Mai nhắn: tháng này đáng lẽ nhà mình dư tiền xăng, mà cuối tháng em không thấy đồng nào. Anh Thắng trả lời: tại nó tan vào chi tiêu hằng ngày hết rồi. Tiền rẻ ra từng lít một, ít ai để ý, nên cũng ít ai giữ lại được.'}, {'k': 'cards', 'ch': 'Chương 5 – Ba cách dùng tiền xăng rẻ', 'anh': 'ov:Hanoi apartment buildings||Hanoi apartment buildings', 'cap': ('3 CÁCH DÙNG', 'TIỀN XĂNG RẺ ĐI MỖI THÁNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('Tiêu luôn', 'Để tan vào chi tiêu', 'KHÔNG THẤY ĐÂU'), ('Để riêng một nửa', 'Khoảng 350 nghìn mỗi tháng', 'CÓ QUỸ NHỎ'), ('Để riêng hết', 'Khoảng 700 nghìn mỗi tháng', 'SẴN SÀNG THÁNG 4/2027')], 'say': 'Anh Thắng thấy có ba cách. Một, cứ để tiền xăng rẻ tan vào chi tiêu như tháng này. Hai, mỗi tháng để riêng một nửa, khoảng ba trăm năm mươi nghìn. Ba, để riêng toàn bộ phần chênh, khoảng bảy trăm nghìn, làm quỹ cho ngày thuế xăng hết hạn hoặc giá dầu quay lại. Không cách nào đúng cho mọi nhà, tuỳ thu nhập và nợ của từng người.'}, {'k': 'chat', 'cap': ('"MỖI LẦN ĐỔ XĂNG', 'ANH CHUYỂN PHẦN CHÊNH"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Chị Mai', 'tv': 'Đang hoạt động', 'gio': '21:30', 'mau': (56, 189, 248), 'msgs': [('me', 'Mỗi lần đổ xăng anh chuyển phần chênh sang tài khoản riêng'), ('me', 'Để dành cho lúc xăng đắt lại'), ('Chị Mai', 'Vậy em cũng để riêng tiền điện giảm')]}, 'say': 'Anh Thắng nhắn vợ kế hoạch. Mỗi lần đổ xăng, anh sẽ chuyển phần chênh so với giá tháng ba sang một tài khoản riêng, để dành cho lúc xăng đắt lại. Chị Mai trả lời rằng chị cũng sẽ để riêng phần tiền điện được giảm. Đó là lựa chọn của gia đình anh Thắng, không phải lời khuyên chung cho mọi người.'}, {'k': 'checklist', 'ch': 'Chương 6 – Phép thử cho chi tiêu', 'anh': 'ov:Hanoi skyline night||Hanoi skyline night', 'cap': ('PHÉP THỬ', 'TIỀN XĂNG RẺ ĐI ĐÂU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Để riêng được toàn bộ', (34, 197, 94)), ('Để riêng được một nửa', (255, 196, 0)), ('Tan hết vào chi tiêu', (239, 68, 68))], 'say': 'Em gợi ý một phép thử tự soi. Anh chị tính xem mỗi tháng nhà mình đổ bao nhiêu lít xăng, nhân với số tiền rẻ hơn mỗi lít. Rồi hỏi: phần tiền đó đang ở đâu? Nếu để riêng được toàn bộ, nhà mình đã có quỹ cho lúc xăng đắt lại. Nếu được một nửa, vẫn ổn. Nếu tan hết vào chi tiêu, thì ngày xăng tăng lại, ngân sách sẽ hụt ngay. Đây là mốc tự soi, không phải lời khuyên.'}, {'k': 'checklist', 'anh': 'ov:Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'cap': ('3 ĐIỀU CẦN THEO DÕI', 'TỪ NAY TỚI THÁNG 4/2027'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Giá xăng mỗi thứ Năm', (255, 196, 0)), ('CPI tháng 11, đầu tháng 12', (255, 196, 0)), ('Thuế xăng hết hạn 31/3/2027', (239, 68, 68))], 'say': 'Ba điều đáng theo dõi. Giá xăng điều chỉnh vào chiều thứ Năm hằng tuần, theo giá dầu và đồng đô la. Chỉ số giá tháng mười một, Cục Thống kê công bố đầu tháng mười hai, xem xăng và điện giảm có kéo được giá cả xuống không. Và ngày ba mươi mốt tháng ba năm hai nghìn không trăm hai mươi bảy, khi thuế xăng về không phần trăm hết hạn. Muốn hiểu lạm phát ăn vào tiền tiết kiệm thế nào, anh chị có thể đọc bài miễn phí trên chứng khoán Huy Nguyễn chấm com.'}, {'k': 'chat', 'ch': 'Kết – Tin nhắn cuối ngày', 'cap': ('"XĂNG RẺ LÀ TẠM THỜI', 'TIỀN ĐỂ RIÊNG MỚI LÀ CỦA MÌNH"'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'chat': {'ten': 'Bố', 'tv': 'Đang hoạt động', 'gio': '22:00', 'mau': (255, 196, 0), 'msgs': [('Bố', 'Xăng lên xuống cả đời bố rồi'), ('Bố', 'Lúc rẻ thì phải biết để dành'), ('me', 'Dạ, xăng rẻ là tạm thời, tiền để riêng mới là của mình')]}, 'say': 'Mười giờ tối, bố nhắn: xăng lên xuống cả đời bố rồi, lúc rẻ thì phải biết để dành. Anh Thắng trả lời: dạ, xăng rẻ là tạm thời, tiền để riêng mới là của mình.'}, {'k': 'end', 'cap': ('TIỀN XĂNG RẺ MỖI THÁNG', 'NHÀ ANH CHỊ ĐỂ Ở ĐÂU?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Còn anh chị, mỗi tháng nhà mình tiết kiệm được bao nhiêu từ xăng rẻ, và phần tiền đó đang ở đâu? Kể cho em và mọi người ở phần bình luận nhé.'}]
META = {'NONG1911A': {'kenh': '@chungkhoanhuynguyen', 'seri': 'Tin nóng trong ngày', 'ngay': '2026-11-19', 'gio_goi_y': '19:30', 'gio': '19:30', 'nhac': 'lofi', 'tieu_de': 'Giá Xăng Hôm Nay Rẻ Gần 36% Từ Đỉnh: 30.114 Còn 19.399 Đồng – Sao Đi Chợ Vẫn Đắt Hơn 5%?', 'title': 'Giá Xăng Hôm Nay Rẻ Gần 36% Từ Đỉnh: 30.114 Còn 19.399 Đồng – Sao Đi Chợ Vẫn Đắt Hơn 5%?', 'mo_ta': 'NÓNG: giá xăng E5 từ đỉnh 30.114 đồng/lít tháng 3/2026 xuống 19.399 đồng kỳ 12/11 – rẻ đi gần 36%. Thuế tiêu thụ đặc biệt với xăng về 0% từ 1/11 đến hết 31/3/2027, giá điện giảm 2%. Vậy mà giá cả tháng 10 vẫn cao hơn năm ngoái 5,09%. Vì sao xăng rẻ mà chợ không rẻ, lần trước năm 2022 ra sao, và phép thử cho chi tiêu nhà anh chị.\n\nNguồn số liệu:\n• Ngôi Sao 18/11/2026: kỳ điều hành 15:00 ngày 12/11: E5 RON92 19.399 đ/lít, E10 RON95-III 19.845 đ/lít; từ đầu tháng 11 E5 giảm 6.628 đ/lít; đỉnh E5 30.114 (tháng 3/2026); đỉnh E10 31.420 (24/3/2026); Brent 17/11: 93,14 USD/thùng\n• VietnamPlus 31/10/2026: Nghị quyết 45/2026/NQ-CP – thuế TTĐB xăng 0% từ 1/11/2026 đến hết 31/3/2027; E5 còn 24.223 đ/lít (giảm 1.804)\n• Báo Đầu tư 4/11/2026 (họp báo Chính phủ): giảm thu gần 7.000 tỷ; giá điện bình quân giảm 2% từ 1/11; hai biện pháp làm CPI bình quân năm giảm khoảng 0,08 điểm %; quyền số điện và xăng dầu tổng 9,34%; mục tiêu CPI khoảng 4,5%\n• Nhân Dân 3/11/2026 (Cục Thống kê): CPI tháng 10/2026 +5,09% so cùng kỳ; bình quân 10 tháng +4,57%; lạm phát cơ bản bình quân 10 tháng +4,24%\n• Người Quan Sát 18/11/2026 (khảo sát kỳ vọng lạm phát của NHNN, 1–9/11): các tổ chức tín dụng kỳ vọng CPI tháng 11 +0,34% so tháng 10; bình quân 2026 +4,49%\n• VnEconomy 7/3/2026: giá dầu tăng do xung đột Mỹ – Israel – Iran, eo biển Hormuz bị phong toả\n• Báo Quốc tế 19/11/2026: đồng USD cao nhất 19 tháng (18/11)\n• VnExpress 12/12/2022: RON95 21.200 đ/lít, thấp hơn gần 36% so với đỉnh 32.870 tháng 6/2022. Tuổi Trẻ 29/12/2022 (Tổng cục Thống kê): CPI tháng 12/2022 +4,55% so cùng kỳ; bình quân 2022 +3,15%\n• Tự tính: 30.114 − 19.399 = 10.715 đ (35,6%); 32.870 → 21.200 = rẻ 35,5%; 31.420 → 19.845 = rẻ 36,8%. Sổ chi tiêu anh Thắng là GIẢ ĐỊNH: 65 lít/tháng; tháng 3: 65 × 30.114 ≈ 1,96 triệu; nay 65 × 19.399 ≈ 1,26 triệu; chênh ≈ 696 nghìn; tiền chợ 6 triệu × 5,09% ≈ 305 nghìn\n\nLạm phát và tiền tiết kiệm: https://chungkhoanhuynguyen.com/hoc/\nCần trao đổi riêng về kế hoạch tài chính: Zalo 0365.188.286\n\nNhân vật anh Thắng, chị Mai, bố là hư cấu; số liệu là thật theo nguồn trên.\nChia sẻ góc nhìn, không phải khuyến nghị.', 'tags': ['giá xăng hôm nay', 'giá xăng', 'giá xăng E5', 'thuế tiêu thụ đặc biệt xăng', 'lạm phát', 'CPI tháng 10', 'giá cả', 'chi tiêu gia đình', 'tin nóng tài chính', 'giá dầu'], 'bia_hook': ['XĂNG RẺ 36%', 'CHỢ VẪN ĐẮT?'], 'badge': 'GIÁ XĂNG HÔM NAY', 'bia_anh': 'Ho Chi Minh City skyline night||Ho Chi Minh City skyline night', 'bia_hook_b': ['30.114 ĐỒNG', 'CÒN 19.399'], 'badge_b': 'XĂNG E5 MỖI LÍT', 'bia_hook_c': ['TIỀN XĂNG RẺ', 'ĐI ĐÂU HẾT???'], 'badge_c': 'GIÁ CẢ VẪN TĂNG 5,09%', 'reel_hook': 'XĂNG RẺ GẦN 36%|SAO CHỢ VẪN ĐẮT???', 'fb_post': 'Xăng E5 rẻ gần 36% từ đỉnh ⛽\n\n👉 Tháng 3/2026: 30.114 đồng/lít\n👉 Kỳ 12/11: 19.399 đồng/lít\n👉 Nhưng giá cả tháng 10 vẫn cao hơn năm ngoái 5,09%\n\nTiền xăng rẻ mỗi tháng nhà anh chị để ở đâu?\n🎬 Xem đầy đủ: {LINK}', 'chuong': ['Mở đầu', 'Chương 1 – Giá xăng năm 2026', 'Chương 2 – Vì sao xăng rẻ mà chợ không rẻ?', 'Chương 3 – Lần trước là năm 2022', 'Chương 4 – Sổ chi tiêu nhà anh Thắng', 'Chương 5 – Ba cách dùng tiền xăng rẻ', 'Chương 6 – Phép thử cho chi tiêu', 'Kết – Tin nhắn cuối ngày']}}
